exercises.solution:
import json

def wait_for_order(consumer, order_id, attempts=20):
    for _ in range(attempts):
        msg = consumer.poll(0.5)
        if msg is None or msg.error() is not None:
            continue
        try:
            data = json.loads(msg.value())
        except ValueError:
            continue
        if data.get("order_id") == order_id:
            return data
    return None

