from collections import Counter

def find_duplicates(ids):
    return sorted(i for i, n in Counter(ids).items() if n > 1)

def first_per_order(payments):
    seen, result = set(), []
    for p in payments:
        if p["order_id"] not in seen:
            seen.add(p["order_id"])
            result.append(p)
    return result

